<script setup lang="ts">
/**
 * Search and filters with a clear button and result count (`design/components/filter-bar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/filter-bar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { agentMember } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/filter-bar.module.css'
import Button from '../controls/Button.vue'
import Inline from '../layout/Inline.vue'

export interface FilterResultCount {
  shown: number
  total?: number
}

export interface FilterBarMessages {
  clear: string
  resultCount: (count: FilterResultCount) => string
}

export interface FilterBarProps {
  /**
   * The only input that shows or hides the clear button.
   */
  isFiltered: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: FilterBarMessages
  resultCount?: FilterResultCount
}

defineOptions({ name: 'FilterBar', inheritAttrs: false })

const props = withDefaults(defineProps<FilterBarProps>(), {
  messages: () => ({
    clear: 'Clear filters',
    resultCount: ({ shown, total }: FilterResultCount) =>
      total === undefined ? `${shown} results` : `${shown} of ${total} results`,
  }),
})
const emit = defineEmits<{ clear: [] }>()
defineSlots<{
  default?: (props: Record<string, never>) => unknown
  search?: (props: Record<string, never>) => unknown
}>()
const clearRegion = useTemplateRef<HTMLElement>('clearRegion')
const root = useTemplateRef<HTMLElement>('root')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'FilterBar',
    element: () => root.value,
    state: () => ({
      filtered: props.isFiltered,
      'result-count':
        props.resultCount === undefined ? '' : props.messages.resultCount(props.resultCount),
    }),
    actions: {
      clear: () =>
        (() => {
          if (!props.isFiltered)
            throw new Error('Nothing is filtered, so there is nothing to clear.')
          emit('clear')
        })(),
    },
    withholds: () => clearRegion.value,
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.bar"
    :data-filtered="isFiltered ? '' : undefined"
    data-member="filter-bar"
  >
    <Inline :gap="3" align="center" :wrap="true">
      <slot name="search" />
      <slot />
      <!-- clear -->
      <span v-if="isFiltered" ref="clearRegion" :class="styles.clear">
        <Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="clear"
          :label="messages.clear"
          @click="emit('clear')"
        />
      </span>
      <!-- count -->
      <span v-if="resultCount !== undefined" :class="styles.count" aria-live="polite">
        {{ messages.resultCount(resultCount) }}
      </span>
    </Inline>
  </div>
</template>
